<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, statusText } from '../api'
import ProductImage from '../components/ProductImage.vue'
import ImageViewer from '../components/ImageViewer.vue'
import FilterSelect from '../components/FilterSelect.vue'
import PageState from '../components/PageState.vue'
const route=useRoute();const router=useRouter();const id=route.params.id as string;const product=ref<any>(null);const images=ref<any[]>([]);const loading=ref(false);const saving=ref(false);const uploading=ref(false);const canEdit=ref(false);const error=ref('');const notice=ref('');const viewType=ref('standard');const fileInput=ref<HTMLInputElement>();const viewer=ref<{attachment_id:string;title:string}|null>(null);const form=reactive({name:'',spec:'',unit:'',sale_price:'',remark:''})
const viewNames:Record<string,string>={standard:'标准图',front:'正面',side:'侧面',back:'后面',top:'顶面',bottom:'底面',interior:'内里',other:'其他'}
async function load(){loading.value=true;error.value='';try{const[p,i]=await Promise.all([api<any>(`/products/${id}`),api<{items:any[]}>(`/products/${id}/images`)]);product.value=p;images.value=i.items;Object.assign(form,{name:p.name,spec:p.spec||'',unit:p.unit,sale_price:p.sale_price!=null?String(p.sale_price):'0',remark:p.remark||''})}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';try{await api(`/products/${id}`,{method:'PATCH',body:JSON.stringify({version:product.value.version,name:form.name,spec:form.spec||null,unit:form.unit,sale_price:String(form.sale_price||'0'),remark:form.remark||null})});notice.value='产品资料已保存，工序路线保持不变';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function removeImage(image:any){if(!window.confirm(`确认删除${viewNames[image.view_type]||image.view_type}图片？`))return;error.value='';try{await api(`/products/${id}/images/${image.link_id}`,{method:'DELETE'});notice.value='图片已删除';await load()}catch(e){error.value=(e as Error).message}}
async function visibility(){try{await api(`/products/${id}/visibility`,{method:'POST',body:JSON.stringify({version:product.value.version,visible:product.value.status==='disabled'})});notice.value='产品显示状态已更新';await load()}catch(e){error.value=(e as Error).message}}
async function remove(){if(!window.confirm('确认删除该产品？仅未投入生产的产品可删除。'))return;try{await api(`/products/${id}`,{method:'DELETE'});await router.push('/products/B01')}catch(e){error.value=(e as Error).message}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>20*1024*1024){error.value='图片不能超过20MB';return}uploading.value=true;error.value='';try{const bytes=new Uint8Array(await file.arrayBuffer());const hashBuffer=await crypto.subtle.digest('SHA-256',bytes);const sha256=Array.from(new Uint8Array(hashBuffer),b=>b.toString(16).padStart(2,'0')).join('');const init=await api<{attachment_id:string;chunk_size:number}>('/attachments/init',{method:'POST',body:JSON.stringify({sha256,size_bytes:file.size,mime_type:file.type||'image/jpeg',owner_type:'product'})});const chunkSize=init.chunk_size||4*1024*1024;let index=0;for(let offset=0;offset<file.size;offset+=chunkSize){const chunk=file.slice(offset,offset+chunkSize);await fetch(`/api/v1/attachments/${init.attachment_id}/chunks/${index++}`,{method:'PUT',headers:{Authorization:`Bearer ${localStorage.getItem('clothp_access_token')}`,'Content-Type':'application/octet-stream'},body:chunk}).then(async r=>{if(!r.ok)throw new Error((await r.json()).message)})}await api(`/attachments/${init.attachment_id}/complete`,{method:'POST',body:JSON.stringify({total_chunks:index})});await api(`/products/${id}/images`,{method:'POST',body:JSON.stringify({attachment_id:init.attachment_id,view_type:viewType.value,sort_no:images.value.length+1})});notice.value=`${viewNames[viewType.value]}上传成功`;await load()}catch(e){error.value=(e as Error).message}finally{uploading.value=false;if(fileInput.value)fileInput.value.value=''}}
onMounted(async () => {
  try { const data = await api<{ actions: Record<string, boolean> }>('/me/permissions'); canEdit.value = data.actions['product:write'] === true } catch { canEdit.value = false }
  await load()
})
</script>
<template><div class="page-header"><div><RouterLink to="/products/B01" class="button link">← 返回产品列表</RouterLink><h1>{{product?.name||'产品详情'}}</h1><p>{{product?.product_code}} <span v-if="product" class="status" :class="product.status">{{statusText[product.status]}}</span></p></div><div v-if="canEdit" class="header-actions"><button class="button secondary" @click="visibility">{{product?.status==='disabled'?'显示产品':'隐藏产品'}}</button><button class="button danger" @click="remove">删除产品</button></div></div><div v-if="error" class="notice error">{{error}}</div><div v-if="notice" class="notice success">{{notice}}</div><PageState :loading="loading"/><template v-if="!loading&&product"><section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>基本资料</h2><button v-if="canEdit" class="button" :disabled="saving" @click="save">保存资料</button></div><div class="panel-body"><div class="form-grid"><div class="field"><label>产品名称</label><input :disabled="!canEdit" v-model.trim="form.name"></div><div class="field"><label>规格</label><input :disabled="!canEdit" v-model.trim="form.spec"></div><div class="field"><label>单位</label><input :disabled="!canEdit" v-model.trim="form.unit"></div><div class="field"><label>售价</label><input :disabled="!canEdit" v-model="form.sale_price"></div><div class="field full"><label>备注</label><textarea :disabled="!canEdit" v-model="form.remark" rows="3"></textarea></div></div></div></section><section class="panel"><div class="panel-header"><h2>产品图片</h2><div v-if="canEdit" class="header-actions"><FilterSelect v-model="viewType" :options="Object.entries(viewNames).map(([value,label])=>({value,label}))"/><label class="button">{{uploading?'正在上传…':'上传图片'}}<input ref="fileInput" type="file" accept="image/*" hidden :disabled="uploading" @change="upload"></label></div></div><div class="panel-body"><PageState :empty="!images.length"/><div style="display:flex;gap:18px;flex-wrap:wrap"><div v-for="image in images" :key="image.link_id" style="text-align:center;position:relative"><ProductImage :attachment-id="image.attachment_id" :width="150" :height="150" style="cursor:zoom-in" @click="viewer={attachment_id:image.attachment_id,title:(viewNames[image.view_type]||image.view_type)+' · '+product?.name}"/><button v-if="canEdit" class="image-delete" title="删除图片" @click="removeImage(image)">×</button><p>{{viewNames[image.view_type]||image.view_type}}</p></div></div></div></section></template><ImageViewer v-if="viewer" :attachment-id="viewer.attachment_id" :title="viewer.title" @close="viewer=null"/></template>
<style scoped>
.image-delete { position: absolute; top: -8px; right: -8px; width: 24px; height: 24px; border-radius: 50%; border: none; background: #b42318; color: #fff; font-size: 14px; line-height: 22px; cursor: pointer; box-shadow: 0 2px 6px rgba(0,0,0,.25); }
.image-delete:hover { background: #d92d20; }
</style>
